Translate("deDE", "redridge-mountains", {
	title = "Rotkammgebirge",
	aliases = { "Rotkamm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Rotkammgebirge erhebt sich östlich des {link:elwynn-forest}Waldes von Elwynn{/link}, ein Land aus roten Steinkämmen, hohen Ulmen und schnellen, kalten Flüssen. In seinem Herzen liegt der {link:lake-everstill}Immerruhsee{/link}, und an dessen Westufer steht {link:lakeshire}Seenhain{/link}, die östlichste Gemeinde des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Seine Straßen führen nach Westen nach Elwynn, nach Südwesten in den {link:duskwood}Dämmerwald{/link} und nach Norden durch den Pass in die {link:burning-steppes}Brennende Steppe{/link}. In besseren Jahren war das Rotkammgebirge ein Land der Fischer, Müller und Erzgräber. In diesen Tagen ist es ein Land im Krieg, und es führt diesen Krieg fast allein.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem sich die ersten {link:humans}Menschen{/link} im Rotkammgebirge niederließen. Als {link:stormwind-city}Stormwind{/link} durch die Höfe seines Kernlands reich wurde, breitete sich sein Volk in die umliegenden Hügel aus, und mit der Zeit entstand am Ufer des Sees eine Stadt. Man sagt, die Berge hätten einst weiter nach Norden gereicht. Als die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in ihrem Krieg gegen ihre Verwandten den Feuerfürsten anriefen, brannte das Feuer, das den {link:blackrock-mountain}Blackrock{/link} emporhob, die nördlichen Ketten zu jener aschenerstickten Öde nieder, die heute {link:burning-steppes}Brennende Steppe{/link} heißt. Die südlichen Täler blieben grün, und sie blieben in den Händen der Menschen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:orcs}Orcs{/link} des {link:blackrock-clan}Blackrockclans{/link} sind aus der Brennenden Steppe herabgekommen. Im Bund mit dem Hexenmeister {link:morganth}Morganth{/link} stürmten sie {link:stonewatch-keep}Burg Steinwacht{/link} und erschlugen die meisten Soldaten, die sie hielten. Dann wandte sich der Hexenmeister gegen seine Verbündeten und errichtete im Nordosten einen eigenen Turm, dem die {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link} dienen. Die Orcs drangen bis nach {link:lakeshire}Seenhain{/link} selbst vor, und ihr Angriff war so heftig, dass die große Brücke über den {link:lake-everstill}Immerruhsee{/link} ins Wasser stürzte. {link:magistrate-solomon}Magistrat Solomon{/link} hat nach {link:stormwind-city}Stormwind{/link}, nach {link:westfall}Westfall{/link} und nach {link:darkshire}Dunkelhain{/link} um Hilfe geschrieben. Keine ist gekommen. Die Gemeinde hält sich mit ein paar Wachen, einer wieder aufgebauten Brücke und den Fremden, die ihren Kopfgeldern folgen.

Auch Neues regt sich. Händler einer Handelsgesellschaft haben an der Kreuzung {link:three-corners}Drei Ecken{/link} einen Posten errichtet, und eine neue Straße führt nun aus dem Rotkammgebirge zu den {link:riverglades}Riverglades{/link}. Im fernen Südosten hat eine zweite Kriegsschar der {link:blackrock-mountain}Blackrock{/link} ihr Lager in {link:render-s-valley}Renders Tal{/link} aufgeschlagen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das Volk von {link:lakeshire}Seenhain{/link}.{/b} Fischer, Schmiede, Stallknechte und Wirte, die gelernt haben, hinter Barrikaden zu leben.
• {b}Die Wache von {link:stormwind-city}Stormwind{/link}.{/b} Eine kleine Garnison unter {link:marshal-marris}Marschall Marris{/link}, zu wenige für den Krieg, den sie führen muss.
• {b}Die {link:blackrock-clan}Orcs der Blackrock{/link}.{/b} Sie halten {link:stonewatch-keep}Burg Steinwacht{/link}, den nördlichen Pass und die südöstlichen Täler.
• {b}Die {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link}.{/b} Sie streifen im Dienst Morganths durch das {link:galardell-valley}Galardelltal{/link}.
• {b}Die {link:redridge-gnolls}Gnolle des Rotkammgebirges{/link}.{/b} Ein eigenes Rudel, das {link:razorfen-downs}die Hügel{/link} nördlich von Seenhain und die südliche Straße überfällt.
• {b}{link:murlocs}Murlocs{/link}.{/b} Sie sind die Flüsse heraufgekommen, um den {link:lake-everstill}Immerruhsee{/link} leer zu fischen, fern von jedem Meer.
• {b}Schwarze Drachenwelpen.{/b} Sie jagen in den Hügeln südlich des Sees, und niemand kann sagen, woher sie kommen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Erste Krieg.{/b} Als die {link:horde}Horde{/link} durch das {link:dark-portal}Dunkle Portal{/link} kam, brannte sie überall im Rotkammgebirge Dörfer nieder, wie in {link:elwynn-forest}Elwynn{/link} und {link:westfall}Westfall{/link}.
• {b}Der Zweite Krieg und danach.{/b} Die Horde wurde zerschlagen, und was vom {link:blackrock-clan}Blackrockclan{/link} übrig blieb, zog sich in den {link:blackrock-mountain}Blackrock{/link} zurück.
• {b}Die Gegenwart.{/b} Nun sind die Blackrock wieder nach Süden gekommen, und das Rotkammgebirge ist zur Ostfront des Königreichs geworden.]=],
		},
		{
			title = "Überlieferungen der Berge",
			text = [=[• Der {link:lake-everstill}Immerruhsee{/link} ist berühmt für seine gefleckten Sonnenfische. Die Fischer erzählen auch von etwas weit Größerem, das sich im tiefen Wasser bewegt.
• Rethbanerz ist zu weich, um mit Eisen mithalten zu können, doch seine dunkle, matte Farbe ergibt eine begehrte Tinte für Schreiber.
• {link:marshal-marris}Marschall Marris{/link} gab dem Wildschwein, das die Gärten von {link:lakeshire}Seenhain{/link} zertrampelt, einen Namen: {link:bellygrub}Bellygrub{/link}.]=],
		},
	},
})

Translate("deDE", "lakeshire", {
	title = "Seenhain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Seenhain liegt am Westufer des Immerruhsees, eine Stadt aus Steinhäusern mit einem geschäftigen Gasthaus, einem Rathaus und einem Stall. Sie wird von {link:magistrate-solomon}Magistrat Solomon{/link} und seinem Gericht regiert und von {link:marshal-marris}Marschall Marris{/link} und einer kleinen Garnison von Soldaten Stormwinds bewacht. Barrikaden schließen nun ihren Nordrand ab. Die Arbeiter von {link:foreman-oslow}Vorarbeiter Oslow{/link} mühen sich, die Brücke über den {link:lake-everstill}Immerruhsee{/link} wieder aufzubauen, die die {link:blackrock-mountain}Blackrock{/link} bei ihrem letzten Angriff zum Einsturz brachten. Das Gasthaus ist das Herz der Stadt. Dort kocht Köchin Breanna, was sie finden kann, der Wirt wartet auf eine Lieferung Getränke, die nie ankommt, und man spricht nur von {link:orcs}Orcs{/link}, Gnollen und der Hilfe, die {link:stormwind-city}Stormwind{/link} versprochen hat.]=],
		},
	},
})

Translate("deDE", "lake-everstill", {
	title = "Immerruhsee",
	aliases = { "Immerruh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Immerruhsee füllt das Herz des Rotkammgebirges, klar und blau unter den roten Kämmen. Seine gefleckten Sonnenfische sind seit Langem der Stolz der Fischer von {link:lakeshire}Seenhain{/link}. Nun sind {link:murlocs}Murlocs{/link} in großer Zahl an seine Ufer gekommen, werfen ihre groben Anker aus und nehmen sich die Fische. Der Hafenmeister findet es seltsam, sie so fern vom Meer zu sehen, und er fragt sich, wovor sie fliehen mögen. Unter dem Wasser liegt mehr als Fisch. Als die {link:blackrock-mountain}Blackrock{/link} ein Boot angriffen, das von der zerstörten Brücke aus übersetzte, sank seine Ladung auf den Grund, und der See hat sie behalten.]=],
		},
	},
})

Translate("deDE", "stonewatch-keep", {
	title = "Burg Steinwacht",
	aliases = { "Steinwacht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Steinwacht war die Festung, die die östlichen Gebiete des Rotkammgebirges für die Krone bewachte. Eine kleine Garnison von Soldaten Stormwinds hielt sie, bis die {link:blackrock-clan}Orcs der Blackrock{/link} kamen, gestärkt durch die dunkle Magie Morganths. Die {link:orcs}Orcs{/link} kämpften mit einer Wildheit, von der die Überlebenden noch heute sprechen, und die Burg fiel. Ihre Mauern beherbergen nun den Kriegsherrn {link:gath-ilzogg}Gath'Ilzogg{/link} und seine Hauptmänner, und von dort überfallen die Orcs das Land nach Norden und Westen in Richtung {link:lakeshire}Seenhain{/link}. {link:magistrate-solomon}Magistrat Solomon{/link} zählt die Burg zu dem Ersten, was das Königreich zurückgewinnen muss.]=],
		},
	},
})

Translate("deDE", "stonewatch-tower", {
	title = "Turm der Steinwacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Turm der Steinwacht ist der Wachturm, der neben {link:stonewatch-keep}Burg Steinwacht{/link} steht. Anders als die Burg überstand er die Schlacht unversehrt, und die {link:orcs}Orcs{/link} nutzen ihn nun als eigenen Ausguck über die Straße von {link:lakeshire}Seenhain{/link}. Auf seiner Spitze, zwischen den Fässern, liegt ein vergessener Krug, der einst einen üblen Schnaps enthielt. Der Hochmagier {link:theocritus}Theocritus{/link} wählte diesen Krug als Versteck für eine seiner Glyphen, damit sein Späherauge in die Gedanken derer blicken konnte, die sich in der Burg befanden.]=],
		},
	},
})

Translate("deDE", "stonewatch-falls", {
	title = "Steinwachtfälle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Unterhalb der {link:stonewatch-keep}Steinwacht{/link} stürzt der Fluss, der den {link:lake-everstill}Immerruhsee{/link} entwässert, den Hang hinab und sammelt sich in einem tiefen Becken in den östlichen Hügeln. Dies sind die Steinwachtfälle. {link:murlocs}Murlocs{/link} haben ihre Hütten an seinen Ufern errichtet und fischen in seinen Wassern, wie es ihre Verwandten an den Ufern des großen Sees tun. Über den Fällen stehen die Mauern der verlorenen Burg. Die Fälle liegen zwischen den {link:orcs}Orcs{/link} der Steinwacht und den Gnollen des Galardelltals, und nur wenige aus {link:lakeshire}Seenhain{/link} kommen heute noch so weit nach Osten.]=],
		},
	},
})

Translate("deDE", "tower-of-ilgalar", {
	title = "Der Turm von Ilgalar",
	aliases = { "Ilgalar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Turm von Ilgalar erhebt sich in den nordöstlichen Hügeln des Rotkammgebirges. Er ist der Unterschlupf des Hexenmeisters {link:morganth}Morganth{/link}, der ihn errichtete, nachdem er sich gegen seine Verbündeten, die {link:orcs}Orcs{/link}, gewandt hatte. {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link} bewachen seine Zugänge, und in den Hallen des Turms hängen die Knochen von Drachen, deren Zweck niemand von außen erraten kann. Nahe seinen Mauern hält eine alte Löwenstatue seit Jahrzehnten einsame Wache. Weit im Westen beobachtet der Magier {link:theocritus}Theocritus{/link} den Turm durch das Auge von Azora in {link:tower-of-azora}seinem eigenen Turm{/link}.]=],
		},
	},
})

Translate("deDE", "galardell-valley", {
	title = "Galardelltal",
	aliases = { "Galardell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Galardelltal liegt im Nordosten des Rotkammgebirges, rund um den Fuß des Turms von {link:tower-of-ilgalar}Ilgalar{/link}. Es ist das Land der {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link}, die dem Hexenmeister {link:morganth}Morganth{/link} dienen. Ihre Lager füllen {link:stranglethorn-vale}das Tal{/link}, und ihr Anführer, {link:lieutenant-fangore}Leutnant Fangore{/link}, hat seinen Posten in dessen nördlichen Ausläufern. Unter ihnen wandeln Dunkelweber, die die Schattenmagie des Hexenmeisters wirken. Reisende, die sich hierher verirren, treffen selten auf einen einzelnen {link:gnolls}Gnoll{/link}. Die Schattenfelle folgen einem Hilferuf schneller als jedes andere Rudel in den Bergen, und Fangores Ruf lässt das ganze Tal herbeieilen.]=],
		},
	},
})

Translate("deDE", "alther-s-mill", {
	title = "Althers Mühle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Althers Mühle ist das Sägewerk von {link:lakeshire}Seenhain{/link}, in den Hügeln nordöstlich der Stadt. {link:foreman-oslow}Vorarbeiter Oslow{/link} ist auf sie angewiesen, um das Holz zu bekommen, das er für den Wiederaufbau der Brücke über den {link:lake-everstill}Immerruhsee{/link} braucht. Sicher arbeiten kann man dort nicht mehr. Große Taranteln haben zwischen den gestapelten Stämmen genistet, und {link:blackrock-clan}Orcs der Blackrock{/link} wurden gesehen, wie sie um die Mühle herumschnüffelten. Oslow gibt dem alten Alther die Schuld an dem Durcheinander. Die Mühle hat auch andere Verwendungen. Ein Agent von {link:si-7}SI:7{/link} namens Lucius bewahrt dort eine verschlossene Truhe auf, und jene, die er in den Künsten der Diebe ausbildet, müssen hingehen und sie öffnen.]=],
		},
	},
})

Translate("deDE", "rethban-caverns", {
	title = "Rethbanhöhlen",
	aliases = { "Rethban" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Rethbanhöhlen reichen tief in die Vorberge nördlich von {link:lakeshire}Seenhain{/link}. Sie tragen ihren Namen nach Bart Rethban, der als Erster das dunkle Erz ihrer Wände fand. Seenhain hielt früher einen Vorrat dieses Erzes, denn Schreiber schätzen seine Farbe für ihre Tinten. Nun leben die {link:redridge-gnolls}Gnolle des Rotkammgebirges{/link} in den Höhlen, und ihre Schufter graben das Erz für sich selbst ab. Die Arbeiter von {link:foreman-oslow}Vorarbeiter Oslow{/link} sind zu sehr mit der Verteidigung der Stadt beschäftigt, um es zu holen. Ein {link:dwarves}Zwerg{/link} der Familie Barleybrew in Seenhain hat die Höhlen zu einer Mutprobe für Krieger gemacht.]=],
		},
	},
})

Translate("deDE", "redridge-canyons", {
	title = "Rotkammschlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Rotkammschlucht schneidet durch {link:razorfen-downs}die Hügel{/link} nördlich von {link:lakeshire}Seenhain{/link}, an der Straße zur Brennenden Steppe. Sie ist das Jagdrevier der {link:redridge-gnolls}Gnolle des Rotkammgebirges{/link}. Schläger und Mystiker streifen über die Kämme oberhalb des Stalls der Stadt und stehlen jedes Pferd, das sich verirrt. Ihr Anführer, {link:yowler}Yowler{/link}, hat seinen Bau in der Schlucht, und in stillen Nächten kann die ganze Stadt sein Rudel in den Hügeln heulen hören. Weiter im Norden, nahe dem Pass, haben die {link:blackrock-mountain}Blackrock{/link} ihr Lager aufgeschlagen, sodass Seenhain von {link:gnolls}Gnoll{/link} und {link:orcs}Orc{/link} gleichermaßen eingeschlossen ist.]=],
		},
	},
})

Translate("deDE", "lakeridge-highway", {
	title = "Uferpfad",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Uferpfad führt von der südlichen Brücke Seenhains nach Osten, am Südufer des Immerruhsees entlang in Richtung {link:stonewatch-keep}Steinwacht{/link}. Er wurde für den Handel gebaut und verbindet die Stadt mit den östlichen Gebieten der Berge. Seit die {link:orcs}Orcs{/link} die Burg eingenommen haben, benutzen ihn nur noch wenige Wagen. {link:gnolls}Gnolle{/link} lagern an der südlichen Straße, {link:murlocs}Murlocs{/link} jagen am Ufer, und Kondore kreisen über den Hügeln. {link:deputy-feldon}Hilfssheriff Feldon{/link} hält an seinem westlichen Ende Wache und bezahlt für jede Nachricht darüber, was sich an ihm zusammenbraut.]=],
		},
	},
})

Translate("deDE", "three-corners", {
	title = "Drei Ecken",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drei Ecken ist die Kreuzung am Westrand des Rotkammgebirges. Von ihr führt eine Straße nach {link:lakeshire}Seenhain{/link}, eine nach {link:goldshire}Goldhain{/link} in {link:elwynn-forest}Elwynn{/link} und eine nach {link:darkshire}Dunkelhain{/link} im {link:duskwood}Dämmerwald{/link}. {link:guard-parker}Wache Parker{/link} patrouilliert auf dem Straßenabschnitt in Richtung Dämmerwald. In diesen Tagen ist die Kreuzung zu einem Ort des Handels geworden. Die Handelskommission von {link:azeroth}Azeroth{/link}, eine Gesellschaft von Händlern, hat hier ihren örtlichen Umschlagplatz eingerichtet, mit Rüstmeistern, Schreibern, Maultieren und einem Stapel Kisten, die auf ihre Prüfung warten. Ihre Kuriere bringen leere Kisten aus dem ganzen Land zurück.]=],
		},
	},
})

Translate("deDE", "render-s-camp", {
	title = "Renders Lager",
	aliases = { "Renders Fels" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Renders Lager ist das Lager der {link:blackrock-mountain}Blackrock{/link} im Nordwesten des Rotkammgebirges, gleich westlich des Passes zur Brennenden Steppe. Hier haben die Champions, die jede Einheit des Heeres der {link:orcs}Orcs{/link} anführen, ihr Quartier. Dahinter liegt Renders Fels, eine große Höhle, in der die Orcs ihre Gefangenen halten. Unter ihnen war ein Korporal aus {link:stormwind-city}Stormwind{/link}, der aus der Schlacht um {link:stonewatch-keep}Burg Steinwacht{/link} verschleppt wurde und dessen Name noch immer vor dem Gasthaus von {link:lakeshire}Seenhain{/link} angeschlagen ist. Fährtenleser der Blackrock durchstreifen {link:razorfen-downs}die Hügel{/link} ringsum und beobachten die Straße aus dem Süden.]=],
		},
	},
})

Translate("deDE", "render-s-valley", {
	title = "Renders Tal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Renders Tal liegt im äußersten Südosten des Rotkammgebirges, zwischen den Hügeln oberhalb der südlichen Wälder. Auch hier haben die {link:blackrock-mountain}Blackrock{/link} Lager errichtet, außer Reichweite der {link:stonewatch-keep}Steinwacht{/link}, und ihre Beschwörer und Vorläufer sammeln sich im Tal, weit außer Reichweite der wenigen Patrouillen Seenhains. {link:marshal-marris}Marschall Marris{/link} wusste von {link:orcs}Orcs{/link} in diesem Winkel der Berge, aber nicht, wie viele es waren. Nun hat sich dort eine Kriegsschar unter einem Orc namens {link:incinerator-gar-im}Verbrenner Gar'im{/link} niedergelassen, dessen Schattenwirker als die gefährlichsten ihrer Art gelten.]=],
		},
	},
})

Translate("deDE", "magistrate-solomon", {
	title = "Magistrat Solomon",
	subtitle = "Magistrat von Seenhain",
	found = "Das Rathaus von Seenhain",
	hint = [=[Sprecht mit dem Richter, der Seenhain von seinem Rathaus aus regiert.]=],
	allegiance = "Königreich Stormwind · Gemeinde Seenhain",
	aliases = { "Solomon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magistrat Solomon regiert die Gemeinde {link:lakeshire}Seenhain{/link} und sitzt ihrem Gericht vor. Er ist ein Mann des Gesetzes und der Schrift, und er hat beides zu Waffen gemacht. Seine Erlasse benennen die Feinde des Königreichs, und seine Kopfgelder bezahlen für ihre Köpfe. Doch am meisten vertraut er seinen Briefen. Immer wieder hat er an die Großen und Mächtigen geschrieben und sie angefleht, seine Stadt zu retten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Solomon spricht für eine vergessene Grenze. Seine Bitten enthüllen eine nach der anderen, dass {link:lakeshire}Seenhain{/link} in seiner Verlassenheit nicht allein ist. Auch {link:westfall}Westfall{/link} und {link:darkshire}Dunkelhain{/link} wurden sich selbst überlassen, und Solomon beginnt zu ahnen, dass in {link:stormwind-city}Stormwind{/link} etwas zutiefst im Argen liegt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hat den Tod als Strafe für jede Hilfe an einen Feind des Königreichs verkündet und vollstreckt sie an den Gnollen der {link:shadowhide-gnolls}Schattenfelle{/link}.
• Er hat Kopfgelder auf {link:gath-ilzogg}Gath'Ilzogg{/link}, {link:lieutenant-fangore}Leutnant Fangore{/link} und {link:incinerator-gar-im}Verbrenner Gar'im{/link} ausgesetzt.
• Er sandte Bitten um Hilfe nach {link:stormwind-city}Stormwind{/link}, an {link:gryan-stoutmantle}Gryan Stoutmantle{/link} in {link:westfall}Westfall{/link} und an {link:lord-ello-ebonlocke}Lord Ebonlocke{/link} in {link:darkshire}Dunkelhain{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Situation von Seenhain",
			hint = "Bringt den Bericht des Magistrats zum Heer in Stormwind.",
			text = [=[Solomons Bericht erzählte die ganze düstere Geschichte: das Bündnis von {link:orcs}Orc{/link} und Hexenmeister, den Fall der Burg, die zerstörte Brücke, den Mangel an Soldaten, Nahrung und Verbänden. Der General in {link:stormwind-city}Stormwind{/link} lobte ihn und versprach Verstärkung, sobald der König das Wort gebe. Solomon las die Antwort zweimal. Er fand sie rätselhaft, und er fürchtete, dass sie den Anfang des Krieges bedeutete, nicht sein Ende.]=],
		},
		{
			title = "Briefe an die Grafschaften",
			hint = [=[Bringt die Bitten des Magistrats nach Westfall und Dunkelhain.]=],
			text = [=[Als Nächstes wandte sich Solomon an seine Nachbarn. {link:gryan-stoutmantle}Stoutmantle{/link} antwortete schweren Herzens: Seine Miliz führte ihren eigenen Krieg. {link:lord-ello-ebonlocke}Lord Ebonlocke{/link} hielt die Bitte beinahe für Wahnsinn, denn {link:darkshire}Dunkelhain{/link} hatte seine {link:the-night-watch}Nachtwache{/link} nur aufgestellt, weil {link:stormwind-city}Stormwind{/link} es ebenfalls im Stich gelassen hatte. Als beide Antworten in seinen Händen lagen, begriff Solomon, dass das Heer sich aus allen drei Grafschaften zurückgezogen hatte. Er nannte es Verrat.]=],
		},
		{
			title = "Die wahren Herren",
			hint = [=[Bringt ernste Nachricht aus der Brennenden Steppe nach Seenhain und weiter zum Regenten.]=],
			text = [=[Aus dem Norden kam die Nachricht, dass die {link:blackrock-mountain}Blackrock{/link} nur Figuren waren und dass der schwarze Drachenschwarm hinter ihnen stand. Solomon sandte sie sofort an Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link}. Der Regent schickte kein Heer zurück. Stattdessen machte er den Boten zu einem Hilfssheriff von {link:stormwind-city}Stormwind{/link}, und Solomon weinte, als er diesen Erlass las.]=],
		},
	},
	mentions = {
		{ text = "Bote nach {link:stormwind-city}Stormwind{/link}" },
		{ text = "Bote nach {link:westfall}Westfall{/link}" },
		{ text = "Bote nach {link:darkshire}Dunkelhain{/link}" },
		{ text = "GESUCHT: {link:gath-ilzogg}Gath'Ilzogg{/link}" },
		{ text = "GESUCHT: {link:lieutenant-fangore}Leutnant Fangore{/link}" },
		{ text = "GESUCHT: {link:incinerator-gar-im}Verbrenner Gar'im{/link}" },
		{
			text = [=[Die wahren Herren, in die {link:burning-steppes}Brennende Steppe{/link}]=],
		},
	},
	bonds = {
		{ id = "bailiff-conacher", name = "Büttel Conacher", note = "Beamter seines Gerichts" },
		{ id = "marshal-marris", name = "Marschall Marris", note = "befehligt die Verteidigung seiner Stadt" },
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "lehnte seine Bitte ab" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "lehnte seine Bitte ab" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "der Regent, an den er sich wendet" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "der Kriegsherr, den er tot sehen will" },
	},
})

Translate("deDE", "bailiff-conacher", {
	title = "Büttel Conacher",
	subtitle = "Büttel des Gerichts von Seenhain",
	found = "Das Rathaus von Seenhain",
	hint = [=[Sprecht mit dem Beamten des Gerichts im Rathaus von Seenhain.]=],
	allegiance = "Gemeinde Seenhain",
	aliases = { "Conacher" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Büttel Conacher dient dem Gericht von {link:lakeshire}Seenhain{/link} an der Seite von {link:magistrate-solomon}Magistrat Solomon{/link}. Er setzt das Gesetz des Magistrats durch, und er hält die Geschäfte des Gerichts in Gang, während der Magistrat seine Briefe schreibt. Als das Gericht die {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link} schuldig sprach, {link:morganth}Morganth{/link} geholfen zu haben, fiel es Conacher zu, das Urteil vollstrecken zu lassen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Conacher zeigt den sturen Stolz von {link:lakeshire}Seenhain{/link}. Selbst unter Belagerung besteht die Stadt darauf, nach dem Gesetz zu kämpfen, und darauf, dass ihre Feinde Verbrecher am Königreich sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bezahlt für jeden Anhänger der {link:shadowhide-gnolls}Schattenfelle{/link}, der vor das Gericht gebracht wird.
• Er spricht für das Gericht, wenn es jenen dankt, die seiner Gerechtigkeit Geltung verschaffen.]=],
		},
	},
	mentions = {
		{ text = "Solomons Gesetz" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "der Richter, dem er dient" },
		{ id = "shadowhide-gnolls", name = "Schattenfelle", note = "von seinem Gericht verurteilt" },
	},
})

Translate("deDE", "marshal-marris", {
	title = "Marschall Marris",
	subtitle = "Marschall von Seenhain",
	found = "Der Nordrand von Seenhain, bei den Arbeiten an der Brücke",
	hint = [=[Sprecht mit dem Marschall, der die Verteidigung von Seenhain befehligt.]=],
	allegiance = "Königreich Stormwind · Armee von Stormwind",
	aliases = { "Marris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marschall Marris befehligt die Soldaten von {link:lakeshire}Seenhain{/link}. Er hat die Schlacht um {link:stonewatch-keep}Burg Steinwacht{/link} verloren, und nun muss er die Stadt mit dem Wenigen halten, was übrig ist. Er ist ein praktisch denkender Soldat. Er weiß, dass Tapferkeit allein diesen Krieg nicht gewinnen wird, und er zählt seine Feinde an den Äxten, Kugeln und Köpfen, die ihm gebracht werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Marris ist das Schwert von {link:lakeshire}Seenhain{/link}, wie {link:magistrate-solomon}Solomon{/link} seine Stimme ist. Während der Magistrat Briefe schreibt, führt der Marschall den Krieg, den sonst niemand führen will, gegen einen Feind, der ihm in jedem Tal zahlenmäßig überlegen ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält {link:lakeshire}Seenhain{/link} mit einer kleinen Garnison gegen die {link:blackrock-mountain}Blackrock{/link}.
• Er jagt die Vorläufer der Blackrock, die der Straße nach {link:stonewatch-keep}Steinwacht{/link} auflauern.
• Er vernichtet die dunklen Kugeln der Schattenwirker der Blackrock.
• Er führt einen Krieg des Hungers gegen die Lager der {link:orcs}Orcs{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Bedrohung durch die Blackrock",
			hint = "Helft dem Marschall, die Reihen der Blackrock zu lichten.",
			text = [=[Die {link:orcs}Orcs{/link} kamen aus der Brennenden Steppe, nahmen die Burg ein und sperrten das Volk von {link:lakeshire}Seenhain{/link} in seiner eigenen Stadt ein. Marris verlangte ihre Äxte als Beweis und dann den Kopf von {link:tharil-zun}Tharil'zun{/link}, dem listigen Orc, der die Hinterhalte an der Straße nach {link:stonewatch-keep}Steinwacht{/link} anführte.]=],
		},
		{
			title = "Schattenmagie",
			hint = [=[Bringt dem Marschall die dunklen Kugeln der Zauberwirker der Blackrock.]=],
			text = [=[Die {link:blackrock-mountain}Blackrock{/link} hatten Schattenwirker mitgebracht, und mit ihnen kamen Mitternachtskugeln, von Dämonen verdorben. Diese Kugeln hatten viele Verteidiger des Rotkammgebirges niedergestreckt. Marris wollte sie nicht behalten. Er sandte jede einzelne fort, damit sie vernichtet werde.]=],
		},
		{
			title = "Vermisst",
			hint = "Bringt den Soldaten heim, der bei Steinwacht verloren ging.",
			text = [=[{link:corporal-keeshan}Korporal Keeshan{/link} kehrte aus {link:render-s-camp}Renders Fels{/link} zurück, verwundet und allein. Die meisten seines Regiments waren um ihn herum gestorben. Marris zählte es dennoch als Sieg, und er belohnte jene, die den Soldaten heimgebracht hatten.]=],
		},
	},
	mentions = {
		{ text = "Blockade der {link:blackrock-mountain}Blackrock{/link}" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "regiert die Stadt, die er bewacht" },
		{ id = "corporal-keeshan", name = "Korporal Keeshan", note = "sein verlorener Soldat" },
		{ id = "tharil-zun", name = "Tharil'zun", note = "der Orc, den er tot sehen wollte" },
		{ id = "bellygrub", name = "Bellygrub", note = "von ihm benannt" },
	},
})

Translate("deDE", "foreman-oslow", {
	title = "Vorarbeiter Oslow",
	subtitle = "Vorarbeiter an der Brücke über den Immerruhsee",
	found = "Die Brücke über den Immerruhsee, Seenhain",
