		},
		{
			title = "Taten",
			text = [=[• Er sammelt eiserne Pfähle und Nieten, um die Brücke abzustützen.
• Er bittet um Hilfe gegen die Taranteln, die {link:alther-s-mill}Althers Mühle{/link} befallen haben.
• Er liefert Rethbanerz an Schreiber, wenn er die Hände dafür entbehren kann.]=],
		},
	},
	mentions = {
		{ text = "Die verlorenen Werkzeuge" },
		{ text = "Die Brücke über den {link:lake-everstill}Immerruhsee{/link}" },
		{ text = "Rethbanerz" },
		{ text = "Tintenvorräte" },
		{ text = "{link:alther-s-mill}Althers Mühle{/link}" },
	},
	bonds = {
		{ id = "marshal-marris", name = "Marschall Marris", note = "bewacht die Arbeiten an der Brücke" },
	},
})

