Translate("deDE", "wiley-the-black", {
	title = "Wiley der Schwarze",
	subtitle = "Schurke von Seenhain",
	found = "Das Gasthaus von Seenhain",
	hint = [=[Sucht im Gasthaus von Seenhain nach einem Schurken, der Westfall einen Gefallen schuldet.]=],
	allegiance = "Ungebunden",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wiley der Schwarze ist ein Schurke, der im Gasthaus von {link:lakeshire}Seenhain{/link} wohnt. Er schuldet {link:gryan-stoutmantle}Gryan Stoutmantle{/link} einen Gefallen, und Stoutmantle verschonte ihn einst, als er ihn hätte verrotten lassen können. Als die Volksmiliz kam und nach den {link:defias-brotherhood}Defias{/link} fragte, beglich {link:innkeeper-wiley}Wiley{/link} diese Schuld. Es könnte ihn noch das Leben kosten.]=],
		},
