Translate("deDE", "shawn", {
	title = "Shawn",
	subtitle = "Kind aus Seenhain",
	found = "Das Seeufer südlich von Seenhain",
	hint = "Sucht die Kinder, die am Seeufer südlich der Stadt angeln.",
	allegiance = "Gemeinde Seenhain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shawn ist eines der Kinder von {link:lakeshire}Seenhain{/link}. Er verbringt seine Tage mit Angeln am See, zusammen mit seiner Freundin Hilary und ihrem Kätzchen Effsee. Als Hilarys Halskette, ein Geschenk ihres Vaters, ins Wasser fiel, suchte Shawn nach Hilfe. Seine Eltern verbieten ihm, im See zu schwimmen, denn sie sagen, es gebe Ungeheuer darin.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Shawn zeigt, dass die Kindheit in {link:lakeshire}Seenhain{/link} weitergeht, selbst mit {link:orcs}Orcs{/link} in den Hügeln und {link:murlocs}Murlocs{/link} im See. Die Kinder kennen die Gefahren nur als Geschichten, die ihre Eltern erzählen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet um Hilfe, Hilarys verlorene Halskette zu finden, die, wie er glaubt, beim Angeln in den See gefallen ist.]=],
		},
	},
	mentions = {
		{ text = "Hilarys Halskette" },
	},
})

Translate("deDE", "morganth", {
	title = "Morganth",
	subtitle = "Hexenmeister des Turms von Ilgalar",
	found = "Die Spitze des Turms von Ilgalar",
	hint = "Erklimmt den Turm von Ilgalar und stellt Euch seinem Herrn.",
	allegiance = "Er selbst · die Gnolle der Schattenfelle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morganth ist ein menschlicher Hexenmeister, der im Turm von {link:tower-of-ilgalar}Ilgalar{/link} haust. Vor langer Zeit studierte er im Magierturm von {link:stormwind-city}Stormwind{/link}, einer von dreien, die dort gemeinsam lernten. Er verfiel den dunklen Künsten, und als er nicht umkehren wollte, wurde er verbannt. Er nahm ein versiegeltes Buch der Schattenmagie mit. Nun befehligt er die {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link}, spricht durch verzauberte Anhänger zu ihnen und beschwört Dämonen an seine Seite.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Morganth ist der verborgene Urheber des Untergangs des Rotkammgebirges. Es war seine Magie, die die Wildheit der {link:blackrock-mountain}Blackrock{/link} bei {link:stonewatch-keep}Burg Steinwacht{/link} nährte. Er ist auch der Rivale des Hochmagiers {link:theocritus}Theocritus{/link}, der ihn seit Langem von {link:elwynn-forest}Elwynn{/link} aus beobachtet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schloss ein Bündnis mit {link:gath-ilzogg}Gath'Ilzogg{/link} und dem {link:blackrock-clan}Blackrockclan{/link} und half ihnen, {link:stonewatch-keep}Burg Steinwacht{/link} einzunehmen.
• Bald darauf wandte er sich gegen die {link:orcs}Orcs{/link}, errichtete seinen eigenen Turm und band die {link:shadowhide-gnolls}Gnolle der Schattenfelle{/link} an seinen Dienst.
• Er bewahrt Urs Abhandlung über Schattenmagie auf, obwohl er die Siegel, die die Magier von {link:stormwind-city}Stormwind{/link} darauf setzten, nie brach.
• Er sucht die {red:scythe-of-elune}Sense der Elune{/red}.]=],
		},
	},
	chapters = {
		{
			title = "Das zerbrochene Bündnis",
			hint = "Helft Theocritus, in die Burg der Orcs zu blicken.",
			text = [=[Das Auge von {link:tower-of-azora}Azora{/link} zeigte {link:theocritus}Theocritus{/link} einen Hexenmeister im Krieg mit den {link:orcs}Orcs{/link}, denen er einst geholfen hatte. Warum die beiden sich überworfen hatten, konnte nicht einmal {link:magistrate-solomon}Magistrat Solomon{/link} sagen. Um mehr zu erfahren, versteckte der Hochmagier eine Glyphe auf der Spitze des Wachturms neben {link:stonewatch-keep}Burg Steinwacht{/link}, und er begann, die Gedanken der Orcs darin zu lesen.]=],
		},
		{
			title = "Die Sense",
			hint = "Tut, was Theocritus selbst nicht zu tun bereit ist.",
			text = [=[Schließlich erfuhr {link:theocritus}Theocritus{/link}, was Morganth suchte: die Sense der Elune. Er fürchtete, dass der Hexenmeister sie bereits gefunden hatte und dass {link:stormwind-city}Stormwind{/link} bald seine Macht spüren würde. Der Hochmagier wollte sich Morganth nicht selbst stellen, also erklomm ein anderer an seiner Stelle den Turm von {link:tower-of-ilgalar}Ilgalar{/link}. Morganths Anhänger der Schatten kehrte nach {link:elwynn-forest}Elwynn{/link} zurück, und Theocritus erklärte das Königreich für gerettet vor einer schweren Gefahr.]=],
		},
	},
	mentions = {
		{ text = "Solomons Gesetz" },
		{ text = "{link:theocritus}Theocritus{/link}' Bergung" },
		{ text = "Ein wachsames Auge" },
		{ text = "Urs Abhandlung über Schattenmagie" },
	},
	bonds = {
		{ id = "theocritus", name = "Theocritus", note = "sein Rivale" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "sein früherer Verbündeter" },
		{ id = "lieutenant-fangore", name = "Leutnant Fangore", note = "sein Gnollleutnant" },
		{ id = "shadowhide-gnolls", name = "Schattenfelle", note = "seine Diener" },
	},
})

