		{ id = "tharil-zun", name = "Tharil'zun", note = "führt seine Vorläufer an" },
		{ id = "targorr-the-dread", name = "Targorr der Schreckliche", note = "sein Henker" },
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "setzte das Kopfgeld aus" },
	},
})

