Translate("deDE", "bellygrub", {
	title = "Bellygrub",
	subtitle = "Das Wildschwein der Gärten von Seenhain",
	found = "Die Felder südwestlich von Seenhain",
	hint = [=[Stellt Euch dem großen Eber, der auf den Feldern westlich von Seenhain nach Futter sucht.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bellygrub ist ein großer Eber, der auf den Feldern südwestlich von {link:lakeshire}Seenhain{/link} nach Futter sucht. Hin und wieder verirrt er sich in den Garten von {link:martie-jainrose}Martie Jainrose{/link} und frisst oder zertrampelt alles darin. {link:marshal-marris}Marschall Marris{/link} gab ihm seinen Namen, und der ist hängen geblieben. Die Felder, auf denen er wühlt, liegen nahe der Stadt, und sein Hauer ist der Kräuterkundigen eine Belohnung wert.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Von allen Feinden Seenhains ist Bellygrub der einzige, über den die Stadt lachen kann, auch wenn {link:martie-jainrose}Martie Jainrose{/link} nicht lacht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hat {link:martie-jainrose}Martie{/link} Jainroses Narzissen eine ganze Saison lang verdorben.
• Er wühlt zwischen den großen Blutzahnebern der westlichen Felder nach Futter.]=],
		},
	},
	mentions = {
		{ text = "Ein unwillkommener Gast" },
	},
	bonds = {
		{ id = "martie-jainrose", name = "Martie Jainrose", note = "ihr Garten ist sein Festmahl" },
		{ id = "marshal-marris", name = "Marschall Marris", note = "gab ihm seinen Namen" },
	},
})

Translate("deDE", "blackrock-clan", {
	title = "Blackrockclan",
	aliases = { "Blackrock", "Orcs der Blackrock" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die {link:blackrock-mountain}Blackrock{/link} sind einer der ältesten und kriegerischsten Clans der {link:orcs}Orcs{/link}. Sie waren das Rückgrat der alten {link:horde}Horde{/link} und gaben ihr zwei ihrer Kriegshäuptlinge. Lange nach der Niederlage der Horde haben die Blackrock die alten Wege des Krieges bewahrt, und sie haben nie Frieden mit den {link:humans}Menschen{/link} geschlossen.]=],
		},
		{
			title = "Geschichte",
			text = [=[Im {link:first-war}Ersten Krieg{/link} führte der Häuptling der Blackrock, Blackhand, die {link:horde}Horde{/link} als ihr Kriegshäuptling an, auch wenn andere hinter ihm die Fäden zogen. Er wurde von einem der Seinen erschlagen, {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, einem Krieger der Blackrock, der die Horde danach zur Eroberung von {link:stormwind-city}Stormwind{/link} führte. Im {link:second-war}Zweiten Krieg{/link} wurde Doomhammers Horde am {link:blackrock-mountain}Blackrock{/link} zerschlagen, nachdem er {link:anduin-lothar}Anduin Lothar{/link} erschlagen hatte. Die meisten {link:orcs}Orcs{/link} wurden in Lager getrieben. Die Blackrock, die entkamen, suchten Zuflucht in dem Berg, der ihren Namen trägt, und sie halten seine Höhen seither.]=],
		},
		{
			title = "Im Rotkammgebirge",
			text = [=[Nun sind die {link:blackrock-mountain}Blackrock{/link} aus der {link:burning-steppes}Brennenden Steppe{/link} nach Süden gekommen. Unter dem Kriegsherrn {link:gath-ilzogg}Gath'Ilzogg{/link} und mit der dunklen Magie Morganths nahmen sie {link:stonewatch-keep}Burg Steinwacht{/link} ein und brachten die Brücke über den {link:lake-everstill}Immerruhsee{/link} zum Einsturz. Ihre Vorläufer legen an den Straßen Hinterhalte, ihre Schattenwirker tragen von Dämonen verdorbene Kugeln, und ihre Champions lagern am nördlichen Pass. Eine weitere Kriegsschar ist durch {link:render-s-valley}Renders Tal{/link} in den äußersten Südosten eingedrungen. Doch sie sind so weit ins Königreich vorgestoßen, dass sie in den Hügeln nach Nahrung und Waffen suchen müssen, und {link:lakeshire}Seenhain{/link} hofft, sie auszuhungern.]=],
		},
		{
			title = "Die neue Horde",
			text = [=[Nicht jeder {link:blackrock-mountain}Blackrock{/link} blieb beim Clan. {link:eitrigg}Eitrigg{/link}, der einst dem Kriegshäuptling der Blackrock diente, lernte die Dämonenanbeter zu hassen, die sein Volk in die Irre führten. Er dient nun {link:thrall}Thrall{/link} in {link:orgrimmar}Orgrimmar{/link}, fern vom Berg seines alten Clans.]=],
		},
	},
})

Translate("deDE", "shadowhide-gnolls", {
	title = "Schattenfelle",
	aliases = { "Gnolle der Schattenfelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schattenfelle sind ein Clan von {link:gnolls}Gnollen{/link}, der im {link:galardell-valley}Galardelltal{/link} im Nordosten des Rotkammgebirges lebt. Sie dienen dem Hexenmeister {link:morganth}Morganth{/link}. Ihr Anführer ist {link:lieutenant-fangore}Leutnant Fangore{/link}. Ihre Dunkelweber üben eine schattenhafte Magie aus, ihre Meuchler schlagen ungesehen zu, und ihre Schlächter greifen {link:orcs}Orc{/link} und Mensch gleichermaßen an.]=],
		},
		{
			title = "Durch Anhänger gebunden",
			text = [=[Jeder der Schattenfelle trägt einen Anhänger, durch den {link:morganth}Morganth{/link} zu ihnen spricht. Der Hochmagier {link:theocritus}Theocritus{/link} hat Monate damit verbracht, in diese Anhänger einzudringen. Es ist ihm gelungen, durch einige von ihnen eine Botschaft zu senden, und er hofft, eines Tages einen Angriff durch sie zu senden, der jeden {link:gnolls}Gnoll{/link} erstarren ließe, der einen trägt.]=],
		},
		{
			title = "Unter dem Gesetz",
			text = [=[Das Gericht von {link:lakeshire}Seenhain{/link} erklärte die Schattenfelle für schuldig, einem Verbrecher am Königreich geholfen zu haben, ein Verbrechen, das mit dem Tod bestraft wird. {link:bailiff-conacher}Büttel Conacher{/link} bezahlt für ihre Anhänger als Beweis, und der Magistrat hat ein Kopfgeld auf {link:lieutenant-fangore}Fangore{/link} selbst ausgesetzt.]=],
		},
		{
			title = "Feinde aller",
			text = [=[Die Schattenfelle sind keine Freunde der {link:blackrock-mountain}Blackrock{/link}. Als {link:morganth}Morganth{/link} sich gegen seine Verbündeten, die {link:orcs}Orcs{/link}, wandte, wandten sich seine {link:gnolls}Gnolle{/link} mit ihm, und Orcs sind ebenso sicher durch ihre Hand gestorben wie {link:humans}Menschen{/link}.]=],
		},
	},
})

Translate("deDE", "redridge-gnolls", {
	title = "Gnolle des Rotkammgebirges",
	aliases = { "Rotkammgnolle", "Rudel des Rotkammgebirges" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Gnolle des Rotkammgebirges sind das alte Gnollrudel des Rotkammgebirges, verschieden von den Schattenfellen, die {link:morganth}Morganth{/link} dienen. Sie dienen keinem Hexenmeister und keinem {link:orcs}Orc{/link}. Ihre Schläger und Mystiker durchstreifen {link:razorfen-downs}die Hügel{/link} nördlich von {link:lakeshire}Seenhain{/link}, und ihre Wilderer und Köter lagern an der südlichen Straße. Ihr Anführer ist {link:yowler}Yowler{/link}, der seinen Bau in der {link:redridge-canyons}Rotkammschlucht{/link} hat und dessen Heulen bis nach Seenhain dringt.]=],
		},
		{
			title = "Ihre Art",
			text = [=[Die Gnolle des Rotkammgebirges nehmen, was der Krieg unbewacht lässt. Sie raubten die Karawane, die Eisen für die Brücke über den {link:lake-everstill}Immerruhsee{/link} brachte. Sie stehlen Pferde aus dem Stall von {link:lakeshire}Seenhain{/link}. Sie sind in die {link:rethban-caverns}Rethbanhöhlen{/link} gezogen, wo ihre Schufter das Erz abbauen, das einst die Stadt förderte. Sie sind locker organisiert, doch sie achten Stärke über alles. {link:deputy-feldon}Hilfssheriff Feldon{/link} hofft, dass der Tod ihrer wildesten Drescher die übrigen lehren wird, in den Hügeln zu bleiben. In Rethban führt ein {link:gnolls}Gnoll{/link} namens Ardo Dirtpaw das Rudel an, das die Höhlen hält.]=],
		},
	},
})
